board-cell-activity.code:
const cells = new Map<number, CellActivity>();
for (const access of frame.accesses) {
  for (let address = access.address; address < access.address + access.length && address < MEMORY_SIZE; address++) {
    if (cells.get(address)?.kind === "write") continue;
    cells.set(address, { kind: access.kind, core: access.core, by: access.by });
  }
}
return cells;

board-packet-progress.code:
const answer = packet.type === "mem.data" || packet.type === "mem.ack";
const start = answer ? 0.5 : 0.05;
const end = start + 0.4;
void packets;
if (progress < start || progress > end) return null;
return (progress - start) / (end - start);

board-draw-memory.code:
const activity = cellActivity(frame);
return (
  <g>
    <Label x={MEMORY_AREA.x + MEMORY_AREA.w / 2} y={MEMORY_AREA.y - 3} size={12} weight={700}>
      Memory · 1024 bytes
    </Label>
    <MemoryGrid
      rect={MEMORY_AREA}
      size={MEMORY_SIZE}
      columns={MEMORY_COLUMNS}
      colourOf={(address) => {
        const cell = activity.get(address);
        if (cell) return cell.core !== null ? coreColour(cell.core) : INK.yellow;
        return frame.memory[address] !== 0 ? "#8fb5a3" : null;
      }}
      titleOf={(address) => {
        const cell = activity.get(address);
        return explainCell(address, frame.memory[address], { read: cell?.kind === "read", written: cell?.kind === "write", by: cell?.by });
      }}
    />
  </g>
);

board-draw-bus.code:
const rects = partRects(frame);
const word: Record<Packet["type"], string> = { "mem.read": "read", "mem.data": "data", "mem.write": "write", "mem.ack": "ok", irq: "irq", input: "press", "program.load": "load" };
const peripherals = [...rects].filter(([id]) => id !== "cpu" && id !== "memory");
return (
  <g>
    <Wire path={BUS_LINE} />
    {[...rects.values()].map((rect, i) => (
      <Wire key={i} path={[pinOf(rect), { x: pinOf(rect).x, y: BUS_LINE[0].y }]} />
    ))}
    {peripherals.map(([id, rect]) => (
      <g key={id}>
        <Box rect={rect} fill={id === "you" ? INK.white : INK.darkGreen} shadow={3} />
        <Label x={rect.x + rect.w / 2} y={rect.y + rect.h + 3}>{frame.parts[id]?.label ?? "You"}</Label>
        <Label x={rect.x + rect.w / 2} y={rect.y + rect.h / 2} fill={id === "you" ? INK.outline : INK.white} size={10}>
          {frame.parts[id]?.state ?? "⌨"}
        </Label>
      </g>
    ))}
    {frame.packets.map((packet) => {
      const t = packetProgress(packet, frame.packets, progress);
      const from = rects.get(packet.from);
      const to = rects.get(packet.to);
      if (t === null || !from || !to) return null;
      const colour = packet.core !== null ? coreColour(packet.core) : packet.type === "irq" ? INK.red : INK.lightGrey;
      return <PacketOnWire key={packet.seq} path={wireBetween(from, to)} t={t} word={word[packet.type]} colour={colour} />;
    })}
  </g>
);

