handshake.code:
return new Promise((resolve, reject) => {
  const onMessage = (event: MessageEvent) => {
    const parsed = parseMessage(String(event.data));
    if (!parsed.ok) return;
    const reply = parsed.message;
    if (reply.type === "welcome") {
      socket.removeEventListener("message", onMessage);
      resolve(reply);
    } else if (reply.type === "error") {
      socket.close();
      reject(new Error(`bus refused ${options.id}: ${reply.payload.message}`));
    }
  };
  socket.addEventListener("message", onMessage);
  socket.addEventListener("error", () => reject(new Error(`could not reach the bus at ${socket.url}`)), { once: true });
  socket.addEventListener("open", () => {
    const payload = { role: options.role, label: options.label, ...(options.kind && { kind: options.kind }) };
    socket.send(JSON.stringify(envelope("hello", options.id, "bus", payload, { id: `${options.id}-hello`, tick: 0 })));
  }, { once: true });
});

memory-handler.code:
if (message.type === "mem.read") {
  const { address, length } = message.payload;
  const result = read(memory, address, length);
  if (!result.ok) return void client.reply(message, "fault", { code: "OUT_OF_RANGE", message: result.fault });
  lastRead = { address, length };
  client.reply(message, "mem.data", { address, bytes: result.value });
} else if (message.type === "mem.write" || message.type === "program.load") {
  const { address, bytes } = message.payload;
  const result = write(memory, address, bytes);
  if (!result.ok) return void client.reply(message, "fault", { code: "OUT_OF_RANGE", message: result.fault });
  memory = result.value;
  lastWrite = { address, length: bytes.length };
  client.reply(message, "mem.ack", { address, length: bytes.length });
}

memory-read.code:
const fault = checkRange(address, length);
if (fault) return { ok: false, fault };
return { ok: true, value: memory.bytes.slice(address, address + length) };

memory-write.code:
const fault = checkRange(address, bytes.length);
if (fault) return { ok: false, fault };
if (bytes.some((b) => !Number.isInteger(b) || b < 0 || b > 0xff)) return { ok: false, fault: "every value must be a byte (0-255)" };
const copy = memory.bytes.slice();
copy.splice(address, bytes.length, ...bytes);
return { ok: true, value: { bytes: copy } };

parse-message.code:
let value: unknown;
try {
  value = JSON.parse(raw);
} catch {
  return { ok: false, error: "not valid JSON" };
}
const result = messageSchema.safeParse(value);
if (!result.success) return { ok: false, error: z.prettifyError(result.error) };
return { ok: true, message: result.data };
